# Let me try triangle fill approach
# The 1s on edges seem to be markers
# Let's use (0,17) as top marker and (6,0) as bottom marker
# Fill the triangle between them

def fill_triangle(grid, top_corner, bottom_corner, fill_color=1, special=3):
    result = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    tr, tc = top_corner
    br, bc = bottom_corner

    # Fill triangle from top_corner to bottom_corner
    # For each row between tr and br, fill columns from the triangle edge
    # The triangle edge goes from (tr, tc) to (br, bc)

    # Equation of line: c - tc = (bc - tc)/(br - tr) * (r - tr)
    slope = (bc - tc) / (br - tr) if br != tr else 0

    for r in range(tr + 1, br):  # Fill rows between top and bottom
        # Calculate column at this row on the triangle edge
        edge_col = tc + slope * (r - tr)
        edge_col = int(round(edge_col))

        # Fill from edge_col to the right edge (or left, depending on slope)
        if bc > tc:
            # Positive slope: fill from edge_col to right edge
            for c in range(edge_col, w):
                if result[r][c] not in [1, 4]:  # Don't overwrite existing special values
                    result[r][c] = fill_color
        else:
            # Negative slope: fill from right edge to edge_col
            for c in range(edge_col, w):
                if result[r][c] not in [1, 4]:
                    result[r][c] = fill_color

    # Mark special positions (value 3) as 4
    for r in range(h):
        for c in range(w):
            if result[r][c] == special and 3 in grid[r][c]:  # This won't work
                pass

    # Fix: mark 3s as 4
    for r in range(h):
        for c in range(w):
            if grid[r][c] == special:
                result[r][c] = 4

    return result, result

