    result = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    tr, tc = top_right
    br, bc = bottom_left

    for r in range(tr, br + 1):
        # Calculate which columns should be filled in this row
        # The line from (tr, tc) to (br, bc)

        if tr == br:
            # Horizontal line: fill entire row between tc and bc
            min_c, max_c = min(tc, bc), max(tc, bc)
            for c in range(min_c, max_c + 1):
                if result[r][c] not in [1, 4]:
                    result[r][c] = 1
        else:
            # Stepped line: calculate column for each row
            for i in range(min(tc, bc), max(tc, bc) + 1):
                progress = (i - tc) / (bc - tc) if bc != tc else 0.5
                row_progress = i * (br - tr) + tc if bc != tc else i
                if row_progress >= r and i >= c:
                    result[r][c] = 1
            # Cleaner: just fill between the bounding corners
            min_row = min(tr, br)
            max_row = max(tr, br)
            min_col = min(tc, bc)
            max_col = max(tc, bc)
            for r in range(min_row, max_row + 1):
                for c in range(min(min_col, tc + (bc-tc)*((r-tr)/(br-tr))), 
                                max(max_col, tc + (bc-tc)*((r-tr)/(br-tr)))+1):
                    if grid[r][c] not in [1, 4]:
                        result[r][c] = 1

    # Mark special 3s as 4
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                result[r][c] = 4

    return result

